    def make_trade(self, trade):
        """
        应用成交，并计算交易产生的现金变动。

        开仓：
        delta_cash
        = -1 * margin
        = -1 * amount * contract_multiplier * price * margin_rate

        平仓：
        delta_cash
        = old_margin - margin + delta_realized_pnl
        = (sum of (cost_price * amount) of closed trade) * contract_multiplier            * margin_rate + delta_realized_pnl

        :param trade: IQEngine.model.trade.Trade
        :return: float
        """
        trade_amount = trade.amount
        asset = trade.asset
        contract_multiplier = asset.contract_multiplier
        current_date = trade.trading_datetime
        if trade.entrust_direction == EntrustDirection.BUY:
            if trade.futures_direction == FuturesDirection.OPEN:
                if self.buy_amount == 0:
                    self._long_create_time = current_date
                self._set_position_type(PositionType.RIGHT)
                self._buy_avg_open_price = ((self._buy_avg_open_price * self.buy_amount + trade_amount * trade.price) * contract_multiplier + trade.transaction_cost) / ((self.buy_amount + trade_amount) * contract_multiplier)
                self._buy_transaction_cost += trade.transaction_cost
                self._buy_today_holding_list.insert(0, (trade.price, trade_amount))
                return -1 * self.cal_margin(trade_amount, trade.price)
            else:
                if self.sell_amount - trade_amount != 0:
                    self._sell_avg_open_price = ((self._sell_avg_open_price * self.sell_amount - trade_amount * trade.price) * contract_multiplier - trade.transaction_cost) / ((self.sell_amount - trade_amount) * contract_multiplier)
                else:
                    self._short_clean_time = current_date
                    self._sell_avg_open_price = 0.0
                old_margin = self.margin
                self._sell_transaction_cost += trade.transaction_cost
                delta_realized_pnl = self._close_holding(trade)
                self._sell_realized_pnl += delta_realized_pnl
                return old_margin - self.margin + delta_realized_pnl
        elif trade.futures_direction == FuturesDirection.OPEN:
            if self.sell_amount == 0:
                self._short_create_time = current_date
            self._set_position_type(PositionType.VOLUNTARY)
            self._sell_avg_open_price = ((self._sell_avg_open_price * self.sell_amount + trade_amount * trade.price) * contract_multiplier - trade.transaction_cost) / ((self.sell_amount + trade_amount) * contract_multiplier)
            self._sell_transaction_cost += trade.transaction_cost
            self._sell_today_holding_list.insert(0, (trade.price, trade_amount))
            return -1 * self.cal_margin(trade_amount, trade.price)
        else:
            if self.buy_amount - trade_amount != 0:
                self._buy_avg_open_price = ((self._buy_avg_open_price * self.buy_amount - trade_amount * trade.price) * contract_multiplier + trade.transaction_cost) / ((self.buy_amount - trade_amount) * contract_multiplier)
            else:
                self._long_clean_time = current_date
                self._buy_avg_open_price = 0.0
            old_margin = self.margin
            self._buy_transaction_cost += trade.transaction_cost
            delta_realized_pnl = self._close_holding(trade)
            self._buy_realized_pnl += delta_realized_pnl
            return old_margin - self.margin + delta_realized_pnl
    def _close_holding(self, trade):
        """
        应用平仓，并计算平仓盈亏

        买平：
        delta_realized_pnl = sum of ((trade_price - cost_price)* amount) of closed trades
                             * contract_multiplier

        卖平：
        delta_realized_pnl = sum of ((cost_price - trade_price)* amount) of closed trades
                             * contract_multiplier

        :param trade: IQEngine.model.trade.Trade
        :return: float
        """
        left_amount = trade.amount
        delta = 0
        if trade.entrust_direction == EntrustDirection.BUY:
            if trade.futures_direction == FuturesDirection.CLOSE_TODAY:
                left_amount = trade.amount
                while left_amount > 0 and self._sell_today_holding_list:
                    today_price, today_amount = self._sell_today_holding_list.pop()
                    if today_amount > left_amount:
                        consumed_amount = left_amount
                        self._sell_today_holding_list.append((today_price, today_amount - left_amount))
                    else:
                        consumed_amount = today_amount
                    left_amount -= consumed_amount
                    delta += self._cal_realized_pnl(today_price, trade.price, trade.entrust_direction, consumed_amount)
            else:
                if self._sell_old_holding_list:
                    old_price, old_amount = self._sell_old_holding_list.pop()
                    if old_amount > left_amount:
                        consumed_amount = left_amount
                        self._sell_old_holding_list = [(old_price, old_amount - left_amount)]
                        return self._cal_realized_pnl(old_price, trade.price, trade.entrust_direction, consumed_amount)
                    else:
                        left_amount -= old_amount
                        delta += self._cal_realized_pnl(old_price, trade.price, trade.entrust_direction, old_amount)
                while left_amount > 0 and self._sell_today_holding_list:
                    today_price, today_amount = self._sell_today_holding_list.pop()
                    if today_amount > left_amount:
                        consumed_amount = left_amount
                        self._sell_today_holding_list.append((today_price, today_amount - left_amount))
                    else:
                        consumed_amount = today_amount
                    left_amount -= consumed_amount
                    delta += self._cal_realized_pnl(today_price, trade.price, trade.entrust_direction, consumed_amount)
        elif trade.entrust_direction == EntrustDirection.SELL:
            if trade.futures_direction == FuturesDirection.CLOSE_TODAY:
                left_amount = trade.amount
                while left_amount > 0 and self._buy_today_holding_list:
                    today_price, today_amount = self._buy_today_holding_list.pop()
                    if today_amount > left_amount:
                        consumed_amount = left_amount
                        self._buy_today_holding_list.append((today_price, today_amount - left_amount))
                    else:
                        consumed_amount = today_amount
                    left_amount -= consumed_amount
                    delta += self._cal_realized_pnl(today_price, trade.price, trade.entrust_direction, consumed_amount)
            else:
                if self._buy_old_holding_list:
                    old_price, old_amount = self._buy_old_holding_list.pop()
                    if old_amount > left_amount:
                        consumed_amount = left_amount
                        self._buy_old_holding_list = [(old_price, old_amount - left_amount)]
                        return self._cal_realized_pnl(old_price, trade.price, trade.entrust_direction, consumed_amount)
                    else:
                        left_amount -= old_amount
                        delta += self._cal_realized_pnl(old_price, trade.price, trade.entrust_direction, old_amount)
                while left_amount > 0 and self._buy_today_holding_list:
                    today_price, today_amount = self._buy_today_holding_list.pop()
                    if today_amount > left_amount:
                        consumed_amount = left_amount
                        self._buy_today_holding_list.append((today_price, today_amount - left_amount))
                    else:
                        consumed_amount = today_amount
                    left_amount -= consumed_amount
                    delta += self._cal_realized_pnl(today_price, trade.price, trade.entrust_direction, consumed_amount)
        return delta
    def _cal_realized_pnl(self, cost_price, trade_price, entrust_direction, consumed_amount):
        if entrust_direction == EntrustDirection.BUY:
            return (cost_price - trade_price) * consumed_amount * self.contract_multiplier
        else:
            return (trade_price - cost_price) * consumed_amount * self.contract_multiplier
    def _set_position_type(self, position_type):
        if self._type is None:
            self._type = position_type.value
            return None
